using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;using System.Threading;using Newtonsoft.Json.Linq;using TopoptLab.GH;
class FinalBridgeSmoke {
 static int Main(string[] args){string[] paths={args[0],args[1],args[2]};AppDomain.CurrentDomain.AssemblyResolve+=delegate(object sender,ResolveEventArgs e){foreach(string p in paths)foreach(string ext in new[]{".dll",".gha"}){string f=Path.Combine(p,new AssemblyName(e.Name).Name+ext);if(File.Exists(f))return Assembly.LoadFrom(f);}return null;};try{Test(args[3],args[4],args[2],args[5]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 [MethodImpl(MethodImplOptions.NoInlining)]static JObject Run(JObject request,string config){var job=WorkerJob.Start(request,WorkerJob.Hash(request.ToString()),config);var deadline=DateTime.UtcNow.AddSeconds(120);while(job.Running&&DateTime.UtcNow<deadline)Thread.Sleep(50);if(job.Running){job.Cancel();throw new Exception("Timeout: "+job.Folder);}var result=job.Snapshot();job.Process.Dispose();if(result==null||(string)result["status"]!="completed")throw new Exception("Worker failed: "+job.Folder+" "+result);if(!File.Exists(Path.Combine(job.Folder,"report.html")))throw new Exception("Report missing");return result;}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Test(string fixture,string config,string assemblyFolder,string evidence){
  string loaded=typeof(WorkerJob).Assembly.Location;if(!string.Equals(Path.GetFullPath(loaded),Path.GetFullPath(Path.Combine(assemblyFolder,"TopoptLab.GH.gha")),StringComparison.OrdinalIgnoreCase))throw new Exception("Wrong assembly loaded: "+loaded);
  var request=JObject.Parse(File.ReadAllText(fixture));request["mode"]="fem";var baseline=Run(request,config);request["mode"]="optimize";var design=Run(request,config);
  var surface=Run(new JObject{{"workflow","final_geometry"},{"action","extract"},{"source_result",design},{"settings",new JObject{{"threshold",.1},{"smoothing",0}}},{"manufacturing_review",new JObject{{"enabled",true},{"minimum_wall",1}}}},config);
  if((string)surface["mode"]!="surface"||!(bool)surface["geometry"]["closed"]||(int)surface["geometry"]["solid_components"]!=1)throw new Exception("Invalid surface");if(!File.Exists((string)surface["surface_file"]))throw new Exception("STL missing");
  var final=Run(new JObject{{"workflow","final_geometry"},{"action","analyze"},{"source_result",surface},{"settings",new JObject{{"mesh_size",1.2},{"levels",1},{"backend",request["settings"]["backend"]},{"threads",4}}}},config);
  if((string)final["mode"]!="final_fem"||(string)final["engineering"]["cases"][0]["performance"]["backend"]!=(string)request["settings"]["backend"])throw new Exception("Wrong final backend");var selected=CaseResults.Select(final,2);if((string)selected["load_case"]["name"]!="Half load")throw new Exception("Lost second case");
  var comparison=ResultComparison.Compare(baseline,final);if(comparison["cases"][1]["candidate_stress"]==null)throw new Exception("Final physical stress missing");
  if(new ReviewControlsComponent().Params.Output.Count!=7)throw new Exception("Review outputs missing");var fg=new FinalGeometry3DComponent();if(fg.Params.Input.Count!=13||new FinalFem3DComponent().Params.Input.Count!=9)throw new Exception("Final inputs missing");if(fg.Params.Input[5].Name!="Run"||fg.Params.Input[6].Name!="Stop"||fg.Params.Input[7].Name!="Reset"||!fg.Params.Input[8].Optional||!fg.Params.Input[9].Optional)throw new Exception("Final input compatibility changed");
  File.WriteAllText(evidence,new JObject{{"assembly",loaded},{"backend",request["settings"]["backend"]},{"baseline_report",baseline["engineering"]["report_file"]},{"design_report",design["engineering"]["report_file"]},{"surface_report",surface["engineering"]["report_file"]},{"final_report",final["engineering"]["report_file"]},{"comparison",comparison},{"native_ui_tested",false}}.ToString());
  Console.WriteLine("Final geometry/STL, TET4 FEM, case selection and baseline comparison passed through C#/external Python. Assembly: "+loaded+" | Evidence: "+evidence);
 }
}
